code='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    out = [row[:] for row in grid]
    if not marker_cells:
        return out
    if len({r for r, c in marker_cells}) == 1:
        axis = 0
        marker = marker_cells[0][0]
    else:
        axis = 1
        marker = marker_cells[0][1]
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not obj:
        return out
    vals = [p[axis] for p in obj]
    lo, hi = min(vals), max(vals)
    if marker < lo:
        shift = marker + 1 - lo
    elif marker > hi:
        shift = marker - 1 - hi
    else:
        shift = 0
    for r, c in obj:
        out[r][c] = bg
    moved = [(r + shift, c) if axis == 0 else (r, c + shift) for r, c in obj]
    for r, c in moved:
        out[r][c] = grid[r - shift][c] if axis == 0 else grid[r][c - shift]
    nlo, nhi = lo + shift, hi + shift
    if marker < nlo:
        line = nhi + 1
    else:
        line = nlo - 1
    if axis == 0 and 0 <= line < h:
        out[line] = [8] * w
    elif axis == 1 and 0 <= line < w:
        for r in range(h):
            out[r][line] = 8
    return out
'''
